(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-4-muscle-oian-quiz"]={"title":"Muscle Origin, Insertion, Action & Innervation Set 1 — Anatomy Exam 4","category":"Anatomy","exam":"Exam 4","sem":"summer-1-2026","questions":[{"q":"Which nerve innervates the deltoid?","choices":["Musculocutaneous nerve","Axillary nerve","Radial nerve","Suprascapular nerve"],"answer":1,"exp":"The deltoid is innervated by the axillary nerve (C5–C6). — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the biceps brachii?","choices":["Radial nerve","Musculocutaneous nerve","Ulnar nerve","Median nerve"],"answer":1,"exp":"The biceps brachii (and the other anterior arm flexors) is supplied by the musculocutaneous nerve. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the triceps brachii?","choices":["Musculocutaneous nerve","Axillary nerve","Ulnar nerve","Radial nerve"],"answer":3,"exp":"The triceps brachii (and the other posterior-arm/forearm extensors) is supplied by the radial nerve. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"A lesion of which nerve paralyzes the serratus anterior (producing a winged scapula)?","choices":["Dorsal scapular nerve","Long thoracic nerve","Thoracodorsal nerve","Accessory nerve"],"answer":1,"exp":"The serratus anterior is supplied by the long thoracic nerve (C5–C7); its lesion causes the winged scapula. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the trapezius?","choices":["Dorsal scapular nerve","Accessory nerve (CN XI)","Long thoracic nerve","Thoracodorsal nerve"],"answer":1,"exp":"The trapezius is innervated by the accessory nerve (CN XI). — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the latissimus dorsi?","choices":["Thoracodorsal nerve","Long thoracic nerve","Axillary nerve","Dorsal scapular nerve"],"answer":0,"exp":"The latissimus dorsi is supplied by the thoracodorsal nerve (C6–C8). — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the gluteus maximus?","choices":["Inferior gluteal nerve","Superior gluteal nerve","Femoral nerve","Sciatic nerve"],"answer":0,"exp":"The gluteus maximus is supplied by the inferior gluteal nerve (L5–S2). — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which muscle is innervated by the SUPERIOR gluteal nerve?","choices":["Gluteus maximus","Biceps femoris","Gluteus medius","Adductor magnus"],"answer":2,"exp":"The gluteus medius (with gluteus minimus and tensor fasciae latae) is supplied by the superior gluteal nerve. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the tibialis anterior?","choices":["Superficial fibular nerve","Tibial nerve","Deep fibular (peroneal) nerve","Femoral nerve"],"answer":2,"exp":"The tibialis anterior is supplied by the deep fibular (deep peroneal) nerve (L4–S1). — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which nerve innervates the gastrocnemius?","choices":["Deep fibular nerve","Superficial fibular nerve","Tibial nerve","Femoral nerve"],"answer":2,"exp":"The gastrocnemius (and the rest of the posterior leg) is supplied by the tibial nerve. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"What is the action of the supraspinatus?","choices":["Abduction at the shoulder","Lateral rotation at the shoulder","Medial rotation at the shoulder","Adduction at the shoulder"],"answer":0,"exp":"The supraspinatus abducts the arm at the shoulder. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which rotator cuff muscle produces MEDIAL rotation at the shoulder?","choices":["Subscapularis","Infraspinatus","Teres minor","Supraspinatus"],"answer":0,"exp":"The subscapularis medially rotates the arm at the shoulder. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"What are the actions of the tibialis anterior?","choices":["Plantar flexion and eversion","Plantar flexion and inversion","Dorsiflexion at the ankle and inversion of the foot","Dorsiflexion and eversion"],"answer":2,"exp":"Tibialis anterior dorsiflexes the ankle and inverts the foot. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which muscle EVERTS the foot (and plantar flexes at the ankle)?","choices":["Tibialis anterior","Fibularis (peroneus) longus","Tibialis posterior","Extensor hallucis longus"],"answer":1,"exp":"Fibularis longus everts the foot and plantar flexes the ankle. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"What is the primary action of the biceps femoris?","choices":["Extension at the knee","Dorsiflexion at the ankle","Flexion at the knee (and extension at the hip)","Abduction at the hip"],"answer":2,"exp":"Biceps femoris, a hamstring, flexes the knee and extends the hip. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"What is the action of the masseter?","choices":["Depresses the mandible (opens the mouth)","Protrudes the tongue","Elevates the mandible (closes the jaws)","Elevates the larynx"],"answer":2,"exp":"The masseter elevates the mandible to close the jaws. — Axial Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Which muscle of mastication OPENS the jaws (and protrudes the mandible)?","choices":["Masseter","Temporalis","Medial pterygoid","Lateral pterygoid"],"answer":3,"exp":"The lateral pterygoid opens the jaws and protrudes the mandible. — Axial Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"What are the actions of the rectus femoris (the two-joint quadriceps muscle)?","choices":["Flexion at the knee and extension at the hip","Adduction at the hip","Plantar flexion at the ankle","Extension at the knee and flexion at the hip"],"answer":3,"exp":"Rectus femoris crosses both joints: it extends the knee and flexes the hip. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"The supraspinatus, infraspinatus, and teres minor all insert on which structure?","choices":["Lesser tubercle of the humerus","Deltoid tuberosity of the humerus","Coracoid process of the scapula","Greater tubercle of the humerus"],"answer":3,"exp":"Three of the four rotator cuff muscles (supraspinatus, infraspinatus, teres minor) insert on the greater tubercle of the humerus. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"On which structure does the subscapularis insert?","choices":["Greater tubercle of the humerus","Lesser tubercle of the humerus","Deltoid tuberosity of the humerus","Radial tuberosity"],"answer":1,"exp":"The subscapularis inserts on the lesser tubercle of the humerus. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Where does the deltoid insert?","choices":["Greater tubercle of the humerus","Coracoid process of the scapula","Acromion of the scapula","Deltoid tuberosity of the humerus"],"answer":3,"exp":"The deltoid inserts on the deltoid tuberosity of the humerus. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"On which structure does the biceps brachii insert?","choices":["Ulnar tuberosity","Olecranon of the ulna","Radial tuberosity","Styloid process of the radius"],"answer":2,"exp":"The biceps brachii inserts on the radial tuberosity of the radius. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"All three heads of the triceps brachii insert on which structure?","choices":["Radial tuberosity","Olecranon of the ulna","Coronoid process of the ulna","Greater tubercle of the humerus"],"answer":1,"exp":"All three triceps heads converge to insert on the olecranon of the ulna. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"The gastrocnemius and soleus insert on the calcaneus via which tendon?","choices":["The patellar ligament","The calcaneal (Achilles) tendon","The quadriceps tendon","The plantar aponeurosis"],"answer":1,"exp":"The gastrocnemius and soleus insert on the calcaneus via the calcaneal (Achilles) tendon. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"The gluteus maximus inserts on the iliotibial tract and which femoral landmark?","choices":["Gluteal tuberosity of the femur","Greater trochanter of the femur","Lesser trochanter of the femur","Linea aspera of the femur"],"answer":0,"exp":"Gluteus maximus inserts on the iliotibial tract and the gluteal tuberosity of the femur. — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"},{"q":"Where does the tibialis anterior originate?","choices":["The proximal tibia","The proximal fibula","The distal femur","The calcaneus"],"answer":0,"exp":"Per the lecture, the tibialis anterior originates from the proximal tibia (and inserts on the medial cuneiform and 1st metatarsal base). — Appendicular Musculature - Shahsv.pptx, Slide 73"},{"q":"The gluteus maximus origin spans the iliac crest to which bone?","choices":["The sacrum","The ischial tuberosity","The femur","The pubis"],"answer":0,"exp":"Per the lecture, the gluteus maximus origin spans the iliac crest to the sacrum. — Appendicular Musculature - Shahsv.pptx, Slide 55"},{"q":"Where does the rectus abdominis originate?","choices":["The xiphoid process","The inferior surfaces of ribs 5–7","The iliac crest","The superior surface of the pubis (around the symphysis)"],"answer":3,"exp":"The rectus abdominis originates from the superior surface of the pubis around the symphysis (and inserts on ribs 5–7 and the xiphoid). — Axial Musculature - Shahsv.pptx, Slide 72"},{"q":"The sternocleidomastoid originates by two heads from the sternum and which other bone?","choices":["The mastoid process","The mandible","The hyoid bone","The clavicle"],"answer":3,"exp":"The sternocleidomastoid arises by two heads from the sternum and the clavicle (inserting on the mastoid process). — Axial Musculature - Shahsv.pptx, Slide 43"},{"q":"What are the actions of the gluteus maximus?","choices":["Extension and lateral rotation at the hip","Abduction and medial rotation at the hip","Flexion at the hip","Adduction at the hip"],"answer":0,"exp":"The gluteus maximus extends and laterally rotates the hip (and stabilizes the knee via the iliotibial tract). — Appendicular Musculature — Muscle Reference (Action, Insertion & Innervation)"}]};
